def sliding_window_allowed(timestamps, limit, window):
    from collections import deque
    allowed = deque()
    result = []
    for t in timestamps:
        while allowed and allowed[0] <= t - window:
            allowed.popleft()
        if len(allowed) < limit:
            allowed.append(t)
            result.append(True)
        else:
            result.append(False)
    return result

import re
def parse_duration(s):
    if not s or not re.fullmatch(r'(\d+[hms])+', s):
        raise ValueError(f'invalid format: {s!r}')
    factors = {'h': 3600, 'm': 60, 's': 1}
    total = 0
    for num, unit in re.findall(r'(\d+)([hms])', s):
        total += int(num) * factors[unit]
    return total

def topological_sort(deps):
    from collections import defaultdict, deque
    nodes = set(deps)
    for prereqs in deps.values():
        nodes.update(prereqs)
    indegree = {n: 0 for n in nodes}
    adj = defaultdict(list)
    for node, prereqs in deps.items():
        for pre in prereqs:
            adj[pre].append(node)
            indegree[node] += 1
    queue = deque(sorted(n for n in nodes if indegree[n] == 0))
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in sorted(adj[n]):
            indegree[m] -= 1
            if indegree[m] == 0:
                queue.append(m)
    if len(order) != len(nodes):
        raise ValueError('cycle detected')
    return order

