def _valid(order, deps):
    nodes = set(deps)
    for v in deps.values():
        nodes.update(v)
    if set(order) != nodes or len(order) != len(nodes):
        return False
    pos = {n: i for i, n in enumerate(order)}
    for node, prereqs in deps.items():
        for pre in prereqs:
            if pos[pre] >= pos[node]:
                return False
    return True
