def semver_compare(a, b):
    pa = [int(x) for x in a.split('.')]
    pb = [int(x) for x in b.split('.')]
    n = max(len(pa), len(pb))
    pa += [0] * (n - len(pa))
    pb += [0] * (n - len(pb))
    for x, y in zip(pa, pb):
        if x < y:
            return -1
        if x > y:
            return 1
    return 0

def normalize_path(path):
    if path == '':
        return '.'
    is_abs = path.startswith('/')
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            elif not is_abs:
                stack.append('..')
        else:
            stack.append(part)
    if is_abs:
        return '/' + '/'.join(stack)
    return '/'.join(stack) if stack else '.'
